ps.pstext:
if !IsFeatureImplemented(FEAT_AA64) then
    Undefined();
elsif PSTATE.EL == EL0 then
    if EffectivelyAtEL0NotInHost() && CNTKCTL_EL1().EL0PCTEN == '0' then
        AArch64_SystemAccessTraptoEL1orEL2(0x18);
    elsif EL2Enabled() && !ELIsInHost(EL2) && CNTHCTL_EL2().EL1PCTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif ELIsInHost(EL2) && EffectiveTGEforEL0Traps() == '0' && CNTHCTL_EL2().EL1PCTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectivelyAtEL0InHost() && CNTHCTL_EL2().EL0PCTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        if IsFeatureImplemented(FEAT_ECV_POFF) && EL2Enabled() && (!HaveEL(EL3) || SCR_EL3().ECVEn == '1') && CNTHCTL_EL2().ECV == '1' && EffectivelyAtEL0NotInHost() then
            X{64}(t) = PhysicalCountInt() - CNTPOFF_EL2();
        else
            X{64}(t) = PhysicalCountInt();
        end;
    end;
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && CNTHCTL_EL2().EL1PCTEN == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        if IsFeatureImplemented(FEAT_ECV_POFF) && EL2Enabled() && (!HaveEL(EL3) || SCR_EL3().ECVEn == '1') && CNTHCTL_EL2().ECV == '1' then
            X{64}(t) = PhysicalCountInt() - CNTPOFF_EL2();
        else
            X{64}(t) = PhysicalCountInt();
        end;
    end;
elsif PSTATE.EL == EL2 then
    X{64}(t) = PhysicalCountInt();
elsif PSTATE.EL == EL3 then
    X{64}(t) = PhysicalCountInt();
end;
